{"selected_source_units":["s37","s52"],"charged_context_units":["s0","s28","s29","s37","s52"],"selected_legal_subexpressions":[{"name":"b_domestic_remuneration_test","source":"s37","quote":"paid cash remuneration of $1,000 or more to individuals employed in such domestic service in the calendar year or the preceding calendar year"}],"CURRENT_units":[{"id":"s0","role":"rule","view":null,"text":"§3306. Definitions","context":[]},{"id":"s28","role":"rule","view":null,"text":"(c) Employment","context":["s0"]},{"id":"s29","role":"rule","view":null,"text":"For purposes of this chapter, the term "employment" means any service, of whatever nature,","context":["s28"]},{"id":"s37","role":"rule","view":null,"text":"    (2) domestic service in a private home, local college club, or local chapter of a college fraternity or sorority unless performed for a person who paid cash remuneration of $1,000 or more to individuals employed in such domestic service in the calendar year or the preceding calendar year;","context":["s29"]},{"id":"s52","role":"fact","view":null,"text":"Alice has paid wages of $3200 to Bob for domestic service done in her home from Feb 1st, 2017 to Sep 2nd, 2017, in Baltimore, Maryland, USA.","context":[]}],"accepted_program":"b_remuneration_for_employment = observation(entity='Bob', entity_source='s52', predicate='remuneration for employment', predicate_source='s16')
b_sickness_or_accident_disability = observation(entity='Bob', entity_source='s52', predicate='sickness or accident disability', predicate_source='s19')
b_plan_death = observation(entity='Bob', entity_source='s52', predicate='death', predicate_source='s20')
b_non_cash_trade_payment = observation(entity='Bob', entity_source='s52', predicate='paid in any medium other than cash', predicate_source='s21')
b_outside_trade_or_business = observation(entity='Bob', entity_source='s52', predicate="service not in the course of the employer's trade or business", predicate_source='s21')
b_after_employment_termination = observation(entity='Alice', entity_source='s52', predicate="upon or after the termination of an employee's employment relationship", predicate_source='s23')
b_termination_death = observation(entity='Bob', entity_source='s52', predicate='death', predicate_source='s23')
b_retirement_for_disability = observation(entity='Bob', entity_source='s52', predicate='retirement for disability', predicate_source='s23')
b_would_have_been_paid = observation(entity='Alice', entity_source='s52', predicate="would have been paid if the employee's employment relationship had not been so terminated", predicate_source='s25')
b_agricultural_remuneration = observation(entity='Bob', entity_source='s52', predicate='remuneration for agricultural labor', predicate_source='s26')
b_non_cash_agricultural_payment = observation(entity='Bob', entity_source='s52', predicate='paid in any medium other than cash', predicate_source='s26')
b_service_of_any_nature = observation(entity='Bob', entity_source='s52', predicate='service, of whatever nature', predicate_source='s29')
b_employee_service = observation(entity='Bob', entity_source='s52', predicate='performed by an employee for the person employing him', predicate_source='s30')
b_within_united_states = observation(entity='Bob', entity_source='s52', predicate='within the United States', predicate_source='s30')
b_outside_united_states = observation(entity='Bob', entity_source='s52', predicate='performed outside the United States', predicate_source='s31')
b_united_states_citizen = observation(entity='Bob', entity_source='s52', predicate='a citizen of the United States', predicate_source='s31')
b_american_employer = observation(entity='Alice', entity_source='s52', predicate='an American employer', predicate_source='s31')
b_agricultural_labor = observation(entity='Bob', entity_source='s52', predicate='agricultural labor', predicate_source='s32')
b_private_home_domestic_service = observation(entity='Bob', entity_source='s52', predicate='domestic service in a private home, local college club, or local chapter of a college fraternity or sorority', predicate_source='s37')
b_family_employment = observation(entity='Bob', entity_source='s52', predicate='in the employ of his son, daughter, or spouse', predicate_source='s39')
b_parent_employment = observation(entity='Bob', entity_source='s52', predicate='in the employ of his father or mother', predicate_source='s40')
b_united_states_government_service = observation(entity='Bob', entity_source='s52', predicate='service performed in the employ of the United States Government', predicate_source='s41')
b_state_service = observation(entity='Bob', entity_source='s52', predicate='service performed in the employ of a State, or any political subdivision thereof', predicate_source='s42')
b_school_service = observation(entity='Bob', entity_source='s52', predicate='service performed in the employ of a school, college, or university', predicate_source='s44')
b_enrolled_student = observation(entity='Bob', entity_source='s52', predicate='a student who is enrolled and is regularly attending classes at such school, college, or university', predicate_source='s45')
b_hospital_patient_service = observation(entity='Bob', entity_source='s52', predicate='service performed in the employ of a hospital, if such service is performed by a patient of such hospital', predicate_source='s47')
b_foreign_government_service = observation(entity='Bob', entity_source='s52', predicate='service performed in the employ of a foreign government', predicate_source='s48')
b_student_nurse_service = observation(entity='Bob', entity_source='s52', predicate="service performed as a student nurse in the employ of a hospital or a nurses' training school by an individual who is enrolled and is regularly attending classes in a nurses' training school", predicate_source='s49')
b_international_organization_service = observation(entity='Bob', entity_source='s52', predicate='service performed in the employ of an international organization', predicate_source='s50')
b_penal_institution_service = observation(entity='Bob', entity_source='s52', predicate='service performed by a person committed to a penal institution', predicate_source='s51')
b_general_wage_threshold = residual(source='s4', quote='during the calendar year or the preceding calendar year paid wages of $1,500 or more')
b_general_day_threshold = residual(source='s5', quote='on each of some 10 days during the calendar year or during the preceding calendar year, each day being in a different calendar week, employed at least one individual in employment for some portion of the day')
b_agricultural_wage_threshold = residual(source='s9', quote='during the calendar year or the preceding calendar year paid wages of $20,000 or more for agricultural labor')
b_agricultural_day_threshold = residual(source='s10', quote='on each of some 10 days during the calendar year or during the preceding calendar year, each day being in a different calendar week, employed at least 5 individuals in employment in agricultural labor for some portion of the day')
b_domestic_cash_wage_threshold = residual(source='s12', quote='during the calendar year or the preceding calendar year paid wages in cash of $1,000 or more for such service')
b_unlisted_wage_exclusion = residual(source='s16', quote='except that such term shall not include-')
b_wage_base_exceeded = residual(source='s17', quote='after remuneration (other than remuneration referred to in the succeeding paragraphs of this subsection) equal to $7,000 with respect to employment has been paid to an individual by an employer during any calendar year')
b_employer_plan_or_system = residual(source='s18', quote='under a plan or system established by an employer')
b_unlisted_plan_account = residual(source='s18', quote='on account of-')
b_qualifying_termination_plan = residual(source='s24', quote='under a plan established by the employer which makes provision for his employees generally or a class or classes of his employees')
b_late_survivor_payment = residual(source='s27', quote='after the calendar year in which such employee died')
b_contiguous_country_agreement = residual(source='s31', quote='in a contiguous country with which the United States has an agreement relating to unemployment compensation')
b_unlisted_employment_exception = residual(source='s31', quote='except-')
b_agricultural_cash_test = residual(source='s34', quote='during the calendar year or the preceding calendar year paid remuneration in cash of $20,000 or more to individuals employed in agricultural labor')
b_agricultural_worker_day_test = residual(source='s35', quote='on each of some 10 days during the calendar year or the preceding calendar year, each day being in a different calendar week, employed in agricultural labor (including labor performed by an alien referred to in subparagraph (B)) for some portion of the day (whether or not at the same moment of time) 5 or more individuals')
b_domestic_remuneration_test = residual(source='s37', quote='paid cash remuneration of $1,000 or more to individuals employed in such domestic service in the calendar year or the preceding calendar year')
b_child_under_twenty_one = residual(source='s40', quote='a child under the age of 21')
b_student_spouse_condition = residual(source='s46', quote='by the spouse of such a student, or')
b_domestic_services = residual(source='s6', quote='performing domestic services referred to in paragraph (3)')
b_other_than_domestic_service = residual(source='s14', quote='service other than domestic service referred to in paragraph (3)')
b_admitted_agricultural_alien = residual(source='s36', quote='an alien admitted to the United States to perform agricultural labor pursuant to sections 214(c) and 101(a)(15)(H) of the Immigration and Nationality Act')
@scope('s0')
def definitions_scope():
    return True
@scope('s1')
def employer_scope():
    return definitions_scope
@scope('s2')
def general_employer_scope():
    return employer_scope
@scope('s7')
def agricultural_employer_scope():
    return employer_scope
@scope('s11')
def domestic_employer_scope():
    return employer_scope
@scope('s13')
def special_employer_scope():
    return employer_scope
@scope('s15')
def wages_scope():
    return definitions_scope
@scope('s28')
def employment_scope():
    return definitions_scope
@scope('s38')
def family_service_scope():
    return employment_scope
@scope('s43')
def educational_service_scope():
    return employment_scope
@scope('s32')
def agricultural_labor_scope():
    return (employment_scope and b_agricultural_labor)
@rule('s4', otherwise=False)
def general_wage_test():
    return (general_employer_scope and b_general_wage_threshold)
@rule('s5', otherwise=False)
def general_day_test():
    return (general_employer_scope and b_general_day_threshold)
@rule('s6', otherwise=False)
def domestic_service_disregard():
    return (general_employer_scope and (not b_domestic_services))
@rule('s3', otherwise=False)
def general_employer_definition():
    return (general_employer_scope and domestic_service_disregard and (general_wage_test or general_day_test))
@rule('s9', otherwise=False)
def agricultural_wage_test():
    return (agricultural_employer_scope and b_agricultural_wage_threshold)
@rule('s10', otherwise=False)
def agricultural_day_test():
    return (agricultural_employer_scope and b_agricultural_day_threshold)
@rule('s8', otherwise=False)
def agricultural_employer_definition():
    return (agricultural_employer_scope and (agricultural_wage_test or agricultural_day_test))
@rule('s12', otherwise=False)
def domestic_employer_definition():
    return (domestic_employer_scope and b_domestic_cash_wage_threshold)
@rule('s14', otherwise=False)
def employer_for_other_service():
    return (special_employer_scope and domestic_employer_definition and b_other_than_domestic_service and (general_employer_definition or agricultural_employer_definition))
@rule('s17', otherwise=False)
def wage_base_exclusion():
    return (wages_scope and b_wage_base_exceeded)
@rule('s19', otherwise=False)
def sickness_or_disability_account():
    return (wages_scope and b_sickness_or_accident_disability)
@rule('s20', otherwise=False)
def death_account():
    return (wages_scope and b_plan_death)
@rule('s18', otherwise=False)
def employer_plan_exclusion():
    return (wages_scope and b_employer_plan_or_system and (sickness_or_disability_account or death_account or b_unlisted_plan_account))
@rule('s21', otherwise=False)
def nonbusiness_non_cash_exclusion():
    return (wages_scope and b_non_cash_trade_payment and b_outside_trade_or_business)
@rule('s23', otherwise=False)
def termination_due_to_death_or_disability():
    return (wages_scope and b_after_employment_termination and (b_termination_death or b_retirement_for_disability))
@rule('s24', otherwise=False)
def qualifying_termination_payment_plan():
    return (wages_scope and b_qualifying_termination_plan)
@rule('s25', otherwise=False)
def payment_independent_of_termination():
    return (wages_scope and b_would_have_been_paid)
@rule('s22', otherwise=False)
def termination_payment_exclusion():
    return (wages_scope and termination_due_to_death_or_disability and qualifying_termination_payment_plan and (not payment_independent_of_termination))
@rule('s26', otherwise=False)
def non_cash_agricultural_exclusion():
    return (wages_scope and b_agricultural_remuneration and b_non_cash_agricultural_payment)
@rule('s27', otherwise=False)
def survivor_or_estate_payment_exclusion():
    return (wages_scope and b_late_survivor_payment)
@rule('s16', otherwise=False)
def wages_definition():
    return (wages_scope and b_remuneration_for_employment and (not (wage_base_exclusion or employer_plan_exclusion or nonbusiness_non_cash_exclusion or termination_payment_exclusion or non_cash_agricultural_exclusion or survivor_or_estate_payment_exclusion or b_unlisted_wage_exclusion)))
@rule('s30', otherwise=False)
def domestic_jurisdiction_service():
    return (employment_scope and b_employee_service and b_within_united_states)
@rule('s31', otherwise=False)
def foreign_jurisdiction_service():
    return (employment_scope and b_outside_united_states and (not b_contiguous_country_agreement) and b_united_states_citizen and b_american_employer and (not b_unlisted_employment_exception))
@rule('s34', otherwise=False)
def agricultural_cash_qualification():
    return (agricultural_labor_scope and b_agricultural_cash_test)
@rule('s35', otherwise=False)
def agricultural_worker_day_qualification():
    return (agricultural_labor_scope and b_agricultural_worker_day_test)
@rule('s33', otherwise=False)
def agricultural_employing_person_qualification():
    return (agricultural_labor_scope and (agricultural_cash_qualification or agricultural_worker_day_qualification))
@rule('s36', otherwise=False)
def agricultural_alien_condition():
    return (agricultural_labor_scope and (not b_admitted_agricultural_alien))
@rule('s32', otherwise=False)
def agricultural_labor_exclusion():
    return (agricultural_labor_scope and (not (agricultural_employing_person_qualification and agricultural_alien_condition)))
@rule('s37', otherwise=False)
def domestic_service_exclusion():
    return (employment_scope and b_private_home_domestic_service and (not b_domestic_remuneration_test))
@rule('s39', otherwise=False)
def son_daughter_or_spouse_service_exclusion():
    return (family_service_scope and b_family_employment)
@rule('s40', otherwise=False)
def minor_child_service_exclusion():
    return (family_service_scope and b_child_under_twenty_one and b_parent_employment)
@rule('s41', otherwise=False)
def federal_government_service_exclusion():
    return (employment_scope and b_united_states_government_service)
@rule('s42', otherwise=False)
def state_service_exclusion():
    return (employment_scope and b_state_service)
@rule('s45', otherwise=False)
def enrolled_student_condition():
    return (educational_service_scope and b_enrolled_student)
@rule('s46', otherwise=False)
def student_spouse_condition():
    return (educational_service_scope and b_student_spouse_condition)
@rule('s44', otherwise=False)
def school_service_exclusion():
    return (educational_service_scope and b_school_service and (enrolled_student_condition or student_spouse_condition))
@rule('s47', otherwise=False)
def hospital_patient_service_exclusion():
    return (educational_service_scope and b_hospital_patient_service)
@rule('s48', otherwise=False)
def foreign_government_service_exclusion():
    return (employment_scope and b_foreign_government_service)
@rule('s49', otherwise=False)
def student_nurse_service_exclusion():
    return (employment_scope and b_student_nurse_service)
@rule('s50', otherwise=False)
def international_organization_service_exclusion():
    return (employment_scope and b_international_organization_service)
@rule('s51', otherwise=False)
def penal_institution_service_exclusion():
    return (employment_scope and b_penal_institution_service)
@rule('s29', otherwise=False)
def employment_definition():
    return (employment_scope and b_service_of_any_nature and (domestic_jurisdiction_service or foreign_jurisdiction_service) and (not (agricultural_labor_exclusion or domestic_service_exclusion or son_daughter_or_spouse_service_exclusion or minor_child_service_exclusion or federal_government_service_exclusion or state_service_exclusion or school_service_exclusion or hospital_patient_service_exclusion or foreign_government_service_exclusion or student_nurse_service_exclusion or international_organization_service_exclusion or penal_institution_service_exclusion or b_unlisted_employment_exception)))
query = ('Entailment' if domestic_service_exclusion else 'Contradiction')
